'use client'

import { useEffect, useState } from 'react'
import { Wallet } from '@/types/wallet'
import { fetchUserWallets } from '@/lib/walletapi'
import AddMoneyModal from '@/components/wallet/AddMoneyModal'
// import BuyCryptoModal from '@/components/wallet/BuyCryptoModal'

export default function WalletPage() {
  const [wallets, setWallets] = useState<Wallet[]>([])
  const [loading, setLoading] = useState(true)
  const [showAddModal, setShowAddModal] = useState(false)
  const [showBuyModal, setShowBuyModal] = useState(false)
  const [userId, setUserId] = useState<string>('')

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem('user') || '{}')
    if (user?.id) {
      setUserId(user.id)
      loadWallets(user.id)
    }
  }, [])

  const loadWallets = async (uid: string) => {
    setLoading(true)
    const res = await fetchUserWallets(uid)
    setWallets(res)
    setLoading(false)
  }

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-bold">Your Wallet</h2>
        <div className="flex gap-3">
          <button
            onClick={() => setShowAddModal(true)}
            className="bg-green-600 hover:bg-green-500 px-4 py-2 rounded"
          >
            Add Money
          </button>
          <button
            onClick={() => setShowBuyModal(true)}
            className="bg-blue-600 hover:bg-blue-500 px-4 py-2 rounded"
          >
            Buy Crypto
          </button>
        </div>
      </div>

      {loading ? (
        <p className="text-gray-400">Loading wallets...</p>
      ) : wallets.length === 0 ? (
        <p className="text-gray-400">No wallets found.</p>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {wallets.map((wallet) => (
            <div
              key={wallet.id}
              className="bg-gray-800 border border-gray-700 p-4 rounded"
            >
              <h3 className="text-lg font-semibold">{wallet.token}</h3>
              <p className="text-gray-300 text-sm">
                Balance: {wallet.balance.toFixed(6)} {wallet.token}
              </p>
            </div>
          ))}
        </div>
      )}

      {showAddModal && (
        <AddMoneyModal
          userId={userId}
          onClose={() => {
            setShowAddModal(false)
            loadWallets(userId)
          }}
        />
      )}

      {/* {showBuyModal && (
        <BuyCryptoModal
          userId={userId}
          onClose={() => {
            setShowBuyModal(false)
            loadWallets(userId)
          }}
        />
      )} */}
    </div>
  )
}
